-- Only inserts challenges that weren't already seeded in Phase 1.

with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$Countdown that never ends$$,
    $$python$$,
    $$infinite_loop$$,
    $$medium$$,
    $$countdown$$,
    $$def countdown(n):
    result = []
    while n > 0:
        result.append(n)
    return result$$,
    $$def countdown(n):
    result = []
    while n > 0:
        result.append(n)
        n -= 1
    return result$$,
    $$countdown(n) should return a list counting down from n to 1, e.g. countdown(3) -> [3, 2, 1].$$,
    $$Calling countdown(3) freezes and never returns.$$,
    $$The loop condition (n > 0) never changes because n is never decremented inside the loop, so it runs forever. Every loop needs its condition to eventually become false — always double-check that whatever the condition depends on actually changes each iteration.$$,
    $$[{"input":[3],"expected_output":[3,2,1]},{"input":[1],"expected_output":[1]}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$The loop condition depends on n — does anything inside the loop ever change n?$$ from new_challenge
union all
select id, 2, $$Look at the while loop body — something is missing after result.append(n).$$ from new_challenge
union all
select id, 3, $$Add n -= 1 inside the loop so n eventually reaches 0 and the condition becomes false.$$ from new_challenge;

