    $$isEven$$,
    $$function isEven(n) {
    return n % 2 === 1;
}$$,
    $$function isEven(n) {
    return n % 2 === 0;
}$$,
    $$isEven(n) should return true if n is even, false otherwise.$$,
    $$isEven(4) returns false and isEven(3) returns true — the results are backwards.$$,
    $$n % 2 === 1 is the condition for odd, not even. A number is even when the remainder after dividing by 2 is 0, so the comparison should be === 0. Small logic inversions like this are easy to introduce and easy to miss without testing both true and false cases.$$,
    $$[{"input":[4],"expected_output":true},{"input":[3],"expected_output":false},{"input":[0],"expected_output":true}]$$::jsonb,
    'published'
  )
  returning id
