union all
select id, 2, $$The comparison operator on the return line is checking for the wrong remainder.$$ from new_challenge
union all
select id, 3, $$n % 2 === 0 is true for even numbers; n % 2 === 1 is true for odd numbers. This function needs the first one.$$ from new_challenge;

