    $$Result variable that vanishes after the loop$$,
    $$javascript$$,
    $$scope_error$$,
    $$medium$$,
    $$findFirstNegative$$,
    $$function findFirstNegative(nums) {
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] < 0) {
            let result = nums[i];
        }
    }
    return result;
}$$,
    $$function findFirstNegative(nums) {
    let result = null;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] < 0) {
            result = nums[i];
            break;
        }
    }
    return result;
}$$,
    $$findFirstNegative(nums) should return the first negative number in the array, or null if there isn't one.$$,
    $$Calling findFirstNegative with any array throws: ReferenceError: result is not defined.$$,
    $$result is declared with let inside the if block, so it only exists within that block — it's completely inaccessible once execution reaches the return statement outside the loop. Declare result once, outside the loop, so it's in scope for the whole function.$$,
    $$[{"input":[[3,-2,5]],"expected_output":-2},{"input":[[1,2,3]],"expected_output":null},{"input":[[-5,-2,3]],"expected_output":-5}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$Where is result declared, and where is it being used? Are those the same scope?$$ from new_challenge
union all
select id, 2, $$let and const are block-scoped — look at exactly which block result is declared inside.$$ from new_challenge
union all
select id, 3, $$Move `let result = null;` to before the loop so it's visible both inside the loop and at the return statement.$$ from new_challenge;

