    $$function delayedDouble(n) {
    let result;
    new Promise((resolve) => setTimeout(() => resolve(n * 2), 10)).then((r) => {
        result = r;
    });
    return result;
}$$,
    $$function delayedDouble(n) {
    return new Promise((resolve) => setTimeout(() => resolve(n * 2), 10)).then((r) => r);
}$$,
    $$delayedDouble(n) should asynchronously resolve to n doubled, e.g. delayedDouble(5) eventually resolves to 10.$$,
    $$Awaiting delayedDouble(5) gives undefined instead of 10.$$,
    $$The function returns result immediately, before the Promise's setTimeout callback ever runs — result is still undefined at that point. The function needs to return the Promise itself (or the chained .then()) so callers can await the value once it's actually ready, instead of racing ahead of it.$$,
    $$[{"input":[5],"expected_output":10},{"input":[3],"expected_output":6},{"input":[0],"expected_output":0}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$When does the code inside setTimeout actually run, compared to when the function returns?$$ from new_challenge
union all
select id, 2, $$The function returns result on the line right after starting the Promise — is that too early?$$ from new_challenge
union all
select id, 3, $$Return the Promise chain itself (return new Promise(...).then(...)) instead of a variable that the async callback hasn't filled in yet.$$ from new_challenge;

